using Microsoft.EntityFrameworkCore;
namespace InstallerVault;

public class Library { public string Id { get; set; } = Guid.NewGuid().ToString("N"); public string Path { get; set; } = ""; public bool Active { get; set; } public string Marker { get; set; } = Guid.NewGuid().ToString("N"); }
public class TrackedApp { public string Id { get; set; } = Guid.NewGuid().ToString("N"); public string Name { get; set; } = ""; public string Description { get; set; } = ""; public string Publisher { get; set; } = ""; public bool Paused { get; set; } public int KeepVersions { get; set; } = 2; public DateTime? LastChecked { get; set; } public string? LastError { get; set; } }
public class Source { public string Id { get; set; } = Guid.NewGuid().ToString("N"); public string AppId { get; set; } = ""; public string Provider { get; set; } = ""; public string Identifier { get; set; } = ""; public string Channel { get; set; } = "stable"; public string AssetFilter { get; set; } = ""; public string? MetadataUrl { get; set; } public DateTime? RetrievedAt { get; set; } }
public class Variant { public string Id { get; set; } = Guid.NewGuid().ToString("N"); public string SourceId { get; set; } = ""; public string AppId { get; set; } = ""; public string Key { get; set; } = ""; public string Os { get; set; } = "unknown"; public string Architecture { get; set; } = "unknown"; public string Format { get; set; } = ""; public string? Requirements { get; set; } public bool Tracked { get; set; } public bool Available { get; set; } = true; public string Version { get; set; } = "unknown"; public string ReleaseId { get; set; } = ""; public string Url { get; set; } = ""; public string FileName { get; set; } = ""; public string? ExpectedSha256 { get; set; } public string ArtifactType { get; set; } = "unknown"; }
public class ArchiveFile { public string Id { get; set; } = Guid.NewGuid().ToString("N"); public string LibraryId { get; set; } = ""; public string? AppId { get; set; } public string? VariantId { get; set; } public string RelativePath { get; set; } = ""; public string FileName { get; set; } = ""; public long Size { get; set; } public DateTime ModifiedAt { get; set; } public string? Sha256 { get; set; } public bool Managed { get; set; } public bool Missing { get; set; } public bool Pinned { get; set; } public string Name { get; set; } = ""; public string Version { get; set; } = "unknown"; public string Os { get; set; } = "unknown"; public string Architecture { get; set; } = "unknown"; public string MetadataOrigin { get; set; } = "filename"; public string Confidence { get; set; } = "low"; public string Verification { get; set; } = "not-calculated"; public string ArtifactType { get; set; } = "unknown"; public string DependencyStatus { get; set; } = "unknown"; public string? OfflineTestNotes { get; set; } public string? OfflineTestEnvironment { get; set; } public DateTime? OfflineTestDate { get; set; } public string? OriginalUrl { get; set; } public string? ResolvedUrl { get; set; } public string? ReleaseId { get; set; } public DateTime? DownloadedAt { get; set; } }
public class Job { public string Id { get; set; } = Guid.NewGuid().ToString("N"); public string Kind { get; set; } = "download"; public string LibraryId { get; set; } = ""; public string LibraryPath { get; set; } = ""; public string LibraryMarker { get; set; } = ""; public string? AppId { get; set; } public string? VariantId { get; set; } public string State { get; set; } = "queued"; public string Payload { get; set; } = "{}"; public long Bytes { get; set; } public long? TotalBytes { get; set; } public double BytesPerSecond { get; set; } public int Attempts { get; set; } public string? Error { get; set; } public bool CancelRequested { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime? FinishedAt { get; set; } }
public class Admin { public int Id { get; set; } = 1; public string Username { get; set; } = "admin"; public string PasswordHash { get; set; } = ""; }
public class VaultSettings { public int Id { get; set; } = 1; public int Concurrency { get; set; } = 2; public bool ScheduleEnabled { get; set; } = true; public int CheckHour { get; set; } = 3; public string Timezone { get; set; } = "Europe/London"; public string? LastScheduleDate { get; set; } }
public class VaultDb(DbContextOptions<VaultDb> options) : DbContext(options) {
 public DbSet<Library> Libraries => Set<Library>(); public DbSet<TrackedApp> Apps => Set<TrackedApp>(); public DbSet<Source> Sources => Set<Source>(); public DbSet<Variant> Variants => Set<Variant>(); public DbSet<ArchiveFile> Files => Set<ArchiveFile>(); public DbSet<Job> Jobs => Set<Job>(); public DbSet<Admin> Admins => Set<Admin>(); public DbSet<VaultSettings> Settings => Set<VaultSettings>();
 protected override void OnModelCreating(ModelBuilder b) { b.Entity<ArchiveFile>().HasIndex(x=>new{x.LibraryId,x.RelativePath}).IsUnique(); b.Entity<Variant>().HasIndex(x=>new{x.SourceId,x.Key}).IsUnique(); b.Entity<Library>().HasIndex(x=>x.Path).IsUnique(); }
}
public record ProviderQuery(string Identifier, string Channel = "stable", string AssetFilter = "", string? MetadataUrl = null);
public record ProviderHit(string Identifier, string Name, string Description, string? Url = null);
public record ProviderArtifact(string Key, string Version, string ReleaseId, string Os, string Architecture, string Format, string Url, string FileName, string? Sha256 = null, string ArtifactType = "unknown", string? Requirements = null);
public record ProviderResult(string Name, string Description, string Publisher, List<ProviderArtifact> Artifacts, string? Warning = null);
public interface IProvider { string Id { get; } Task<List<ProviderHit>> SearchAsync(string query, CancellationToken ct); Task<ProviderResult> ResolveAsync(ProviderQuery query, CancellationToken ct); }
public interface ISafeHttp { Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken ct); }
public class VaultOptions { public string DataPath { get; set; } = "data"; public string[] AllowedRoots { get; set; } = []; public string? SetupSecret { get; set; } public string? GitHubToken { get; set; } public string[] PrivateSourceHosts { get; set; } = []; public long MaxDownloadBytes { get; set; } = 50L * 1024 * 1024 * 1024; }
